{
  "name": "高重复频率像增强器",
  "name_en": "High Repetition Rate Image Intensifier",
  "manufacturer": "Kentech",
  "description": "这是一种高重复频率、可门控的像增强器，采用微通道板（MCP）进行弱光放大，并支持外部触发、门控模式和增益相关设置。它常用于高速或时间分辨光学实验中，对瞬态发光、激光诱导过程等弱光信号进行同步增强成像。",
  "description_en": "A high-repetition-rate gated image intensifier that uses a microchannel plate (MCP) to amplify low-light optical signals, with external triggering, gating modes, and gain-related settings. It is commonly used in high-speed or time-resolved optical experiments to synchronously intensify and image transient emission and other weak-light phenomena.",
  "tag_hints": [
    "gated image intensifier",
    "high repetition rate imaging",
    "time-resolved optical diagnostics",
    "MCP gain control",
    "trigger synchronization",
    "weak-light imaging"
  ],
  "actions": [
    {
      "action_name": "auto-clear_async",
      "description": "异步清空设备通信缓冲区。",
      "description_en": "Asynchronously clear the device communication buffer."
    },
    {
      "action_name": "auto-query",
      "description": "向设备发送命令并读取响应。",
      "description_en": "Send a command to the device and read back the response."
    },
    {
      "action_name": "auto-query_expect",
      "description": "向设备发送命令并检查返回内容是否符合预期。",
      "description_en": "Send a command to the device and verify that the reply matches the expected response."
    },
    {
      "action_name": "auto-clear",
      "description": "清空设备通信缓冲区。",
      "description_en": "Clear the device communication buffer."
    },
    {
      "action_name": "auto-remote",
      "description": "设置设备为远程或本地控制模式。",
      "description_en": "Set the device to remote or local control mode."
    },
    {
      "action_name": "auto-revision",
      "description": "读取设备版本信息。",
      "description_en": "Read the device revision information."
    },
    {
      "action_name": "auto-trigger_logic",
      "description": "设置触发逻辑类型。",
      "description_en": "Set the trigger logic type."
    },
    {
      "action_name": "auto-trigger_ttl_termination",
      "description": "设置 TTL 触发终端匹配。",
      "description_en": "Set the TTL trigger termination."
    },
    {
      "action_name": "auto-trigger_edge",
      "description": "设置触发沿类型。",
      "description_en": "Set the trigger edge type."
    },
    {
      "action_name": "auto-trigger_ecl_mode",
      "description": "设置 ECL 触发模式。",
      "description_en": "Set the ECL trigger mode."
    },
    {
      "action_name": "auto-trigger_ecl_level",
      "description": "获取或设置 ECL 触发电平。",
      "description_en": "Get or set the ECL trigger level."
    },
    {
      "action_name": "auto-clamp_voltage",
      "description": "获取或设置门脉冲的箝位电压。",
      "description_en": "Get or set the clamp voltage of the gate pulse."
    },
    {
      "action_name": "auto-average_voltage",
      "description": "获取或设置平均偏置电压。",
      "description_en": "Get or set the average bias voltage."
    },
    {
      "action_name": "auto-status",
      "description": "读取设备状态。",
      "description_en": "Read the device status."
    },
    {
      "action_name": "auto-mcp",
      "description": "设置微通道板电压。",
      "description_en": "Set the microchannel plate voltage."
    },
    {
      "action_name": "auto-mode",
      "description": "设置增益调制工作模式。",
      "description_en": "Set the gain modulation operating mode."
    },
    {
      "action_name": "auto-rfgain",
      "description": "设置射频增益。",
      "description_en": "Set the RF gain."
    },
    {
      "action_name": "auto-temperature",
      "description": "读取设备温度。",
      "description_en": "Read the device temperature."
    },
    {
      "action_name": "auto-enabled",
      "description": "设置微通道板使能状态。",
      "description_en": "Set the microchannel plate enable state."
    }
  ]
}

